        return ResponseEntity.status(status).body(body);
    }

    private Map<String, Object> createView(DatasourceConfig config) {
        Map<String, Object> view = commonView(config);
        view.put("username", config.getUsername());
        view.put("extraParams", config.getExtraParams());
        view.put("status", config.getStatus());
        view.put("createdAt", config.getCreatedAt());
        return view;
