package com.dataconnect.hub.security;

import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.crypto.SecretKey;
import java.nio.charset.StandardCharsets;
import java.util.Date;

@Component
public class JwtUtil {
    private final SecretKey signingKey;
    private final long expiration;

    public JwtUtil(@Value("${jwt.secret}") String secret,
                   @Value("${jwt.expiration}") long expiration) {
        this.signingKey = Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
        this.expiration = expiration;
    }

    public String generateToken(String username, String role) {
        Date issuedAt = new Date();
        Date expiresAt = new Date(issuedAt.getTime() + expiration);
        return Jwts.builder()
                .subject(username)
                .claim("role", role)
                .issuedAt(issuedAt)
                .expiration(expiresAt)
                .signWith(signingKey)
                .compact();
    }

    public String extractUsername(String token) {
        return Jwts.parser()
                .verifyWith(signingKey)
                .build()
                .parseSignedClaims(token)
                .getPayload()
                .getSubject();
    }

    public boolean validateToken(String token) {
        try {
            Jwts.parser().verifyWith(signingKey).build().parseSignedClaims(token);
            return true;
        } catch (Exception ignored) {
            return false;
        }
    }
}

package com.dataconnect.hub.service;

import com.dataconnect.hub.dto.DatasourceConfigRequest;
import com.dataconnect.hub.dto.TestConnectionRequest;
import com.dataconnect.hub.entity.ConnectionLog;
import com.dataconnect.hub.entity.DatasourceConfig;
import com.dataconnect.hub.repository.ConnectionLogRepository;
import com.dataconnect.hub.repository.DatasourceConfigRepository;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

@Service
public class DatasourceConfigService {
    private final DatasourceConfigRepository configRepository;
    private final ConnectionLogRepository logRepository;
    private final DatasourceConnectionService connectionService;

    public DatasourceConfigService(DatasourceConfigRepository configRepository,
                                   ConnectionLogRepository logRepository,
                                   DatasourceConnectionService connectionService) {
        this.configRepository = configRepository;
        this.logRepository = logRepository;
        this.connectionService = connectionService;
    }

    public DatasourceConfig create(Long userId, DatasourceConfigRequest request) {
        DatasourceConfig config = new DatasourceConfig();
        config.setUserId(userId);
        copyRequest(config, request);
        config.setStatus("ACTIVE");
        config.setCreatedAt(LocalDateTime.now());
        return configRepository.save(config);
    }

    public List<DatasourceConfig> list(Long userId) {
        return configRepository.findByUserIdOrderByCreatedAtDesc(userId);
    }

    public Optional<DatasourceConfig> findOwned(Long id, Long userId) {
        return configRepository.findById(id).filter(config -> config.getUserId().equals(userId));
    }

    public DatasourceConfig update(Long id, Long userId, DatasourceConfigRequest request) {
        Optional<DatasourceConfig> found = findOwned(id, userId);
        if (found.isEmpty()) {
            return null;
        }
        DatasourceConfig config = found.get();
        copyRequest(config, request);
        config.setUpdatedAt(LocalDateTime.now());
        return configRepository.save(config);
    }

    public boolean delete(Long id, Long userId) {
        Optional<DatasourceConfig> found = findOwned(id, userId);
        if (found.isEmpty()) {
            return false;
        }
        configRepository.delete(found.get());
        return true;
    }

    public Map<String, Object> testConnection(Long id, Long userId, TestConnectionRequest override) {
        Optional<DatasourceConfig> found = findOwned(id, userId);
        if (found.isEmpty()) {
            return null;
        }
        DatasourceConfig config = found.get();
        String host = nonEmpty(override == null ? null : override.getHost(), config.getHost());
        Integer port = override != null && override.getPort() != null
                ? override.getPort() : config.getPort();
        String databaseName = nonEmpty(override == null ? null : override.getDatabaseName(),
                config.getDatabaseName());
        String username = nonEmpty(override == null ? null : override.getUsername(), config.getUsername());
        String password = *** == null ? null : override.getPassword(), config.getPassword());
        String extraParams = override != null && override.getExtraParams() != null
                ? override.getExtraParams() : config.getExtraParams();

        DatasourceConnectionService.ConnectionTestResult result = connectionService.testConnection(
                config.getDbType(), host, port, databaseName, username, password, extraParams);

        ConnectionLog log = new ConnectionLog();
        log.setConfigId(config.getId());
        log.setUserId(userId);
        log.setJdbcUrl(result.jdbcUrl());
        log.setSuccess(result.success());
        log.setErrorMessage(result.errorMessage());
        log.setCreatedAt(LocalDateTime.now());
        logRepository.save(log);

        Map<String, Object> payload = new LinkedHashMap<>();
        payload.put("success", result.success());
        payload.put("jdbcUrl", result.jdbcUrl());
        if (result.success()) {
            payload.put("responseTimeMs", result.responseTimeMs());
        } else {
            payload.put("errorMessage", result.errorMessage());
        }
        return payload;
    }

    public Map<String, Object> executeQuery(Long id, Long userId, String sql) {
        Optional<DatasourceConfig> found = findOwned(id, userId);
        if (found.isEmpty()) {
            return null;
        }
        DatasourceConfig config = found.get();
        DatasourceConnectionService.QueryResult result = connectionService.executeQuery(
                config.getDbType(), config.getHost(), config.getPort(), config.getDatabaseName(),
                config.getUsername(), config.getPassword(), config.getExtraParams(), sql);
        Map<String, Object> payload = new LinkedHashMap<>();
        if (!result.successful()) {
            payload.put("error", result.error());
            return payload;
        }
        payload.put("columns", result.columns());
        payload.put("rows", result.rows());
        payload.put("rowCount", result.rowCount());
        return payload;
    }

    public List<ConnectionLog> listLogs(Long id, Long userId) {
        if (findOwned(id, userId).isEmpty()) {
            return null;
        }
        return logRepository.findByConfigIdOrderByCreatedAtDesc(id);
    }

    private void copyRequest(DatasourceConfig config, DatasourceConfigRequest request) {
        config.setConfigName(request.getConfigName());
        config.setDbType(request.getDbType());
        config.setHost(request.getHost());
        config.setPort(request.getPort());
        config.setDatabaseName(request.getDatabaseName());
        config.setUsername(request.getUsername());
        config.setPassword(request.getPassword());
        config.setExtraParams(request.getExtraParams());
    }

    private String nonEmpty(String candidate, String fallback) {
        return candidate != null && !candidate.isEmpty() ? candidate : fallback;
    }
}

package com.dataconnect.hub.service;

import org.springframework.stereotype.Service;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.ResultSetMetaData;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@Service
public class DatasourceConnectionService {

    public String buildJdbcUrl(String dbType, String host, Integer port,
                               String databaseName, String extraParams) {
        String scheme = "POSTGRESQL".equalsIgnoreCase(dbType)
                ? "jdbc:postgresql://" : "jdbc:mysql://";
        String url = scheme + host + ":" + port + "/" + databaseName;
        if (extraParams != null && !extraParams.isBlank()) {
            url += "?" + extraParams;
        }
        return url;
    }

    public ConnectionTestResult testConnection(String dbType, String host, Integer port,
                                               String databaseName, String username,
                                               String password, String extraParams) {
        String jdbcUrl = buildJdbcUrl(dbType, host, port, databaseName, extraParams);
        long startedAt = System.currentTimeMillis();
        try (Connection ignored = DriverManager.getConnection(jdbcUrl, username, password)) {
            return new ConnectionTestResult(true, jdbcUrl,
                    System.currentTimeMillis() - startedAt, null);
        } catch (SQLException exception) {
            return new ConnectionTestResult(false, jdbcUrl,
                    System.currentTimeMillis() - startedAt, exception.getMessage());
        }
    }

    public QueryResult executeQuery(String dbType, String host, Integer port,
                                    String databaseName, String username,
                                    String password, String extraParams, String sql) {
        String jdbcUrl = buildJdbcUrl(dbType, host, port, databaseName, extraParams);
        try (Connection connection = DriverManager.getConnection(jdbcUrl, username, password);
             Statement statement = connection.createStatement();
             ResultSet resultSet = statement.executeQuery(sql)) {
            ResultSetMetaData metadata = resultSet.getMetaData();
            int columnCount = metadata.getColumnCount();
            List<String> columns = new ArrayList<>(columnCount);
            for (int i = 1; i <= columnCount; i++) {
                columns.add(metadata.getColumnLabel(i));
            }

            List<Map<String, String>> rows = new ArrayList<>();
            while (resultSet.next()) {
                Map<String, String> row = new LinkedHashMap<>();
                for (int i = 1; i <= columnCount; i++) {
                    row.put(columns.get(i - 1), resultSet.getString(i));
                }
                rows.add(row);
            }
            return new QueryResult(columns, rows, rows.size(), null);
        } catch (SQLException exception) {
            return new QueryResult(null, null, 0, exception.getMessage());
        }
    }

    public record ConnectionTestResult(boolean success, String jdbcUrl,
                                       long responseTimeMs, String errorMessage) {
    }

    public record QueryResult(List<String> columns, List<Map<String, String>> rows,
                              int rowCount, String error) {
        public boolean successful() {
            return error == null;
        }
    }
}
